import json
f="9abfc284-9894-4667-b9ad-a2ff74df6f6f.jsonl"
lines=open(f).read().splitlines()
print("total lines:", len(lines))
# print last few user + assistant text messages
def txt(m):
    c=m.get("message",{}).get("content")
    if isinstance(c,str): return c
    if isinstance(c,list):
        out=[]
        for b in c:
            if b.get("type")=="text": out.append(b["text"])
            elif b.get("type")=="tool_use": out.append(f"[tool {b.get('name')}] "+json.dumps(b.get('input',{}))[:200])
            elif b.get("type")=="tool_result":
                r=b.get("content")
                if isinstance(r,list): r=" ".join(x.get("text","") for x in r if isinstance(x,dict))
                out.append("[result] "+str(r)[:200])
        return "\n".join(out)
    return ""
for l in lines[-30:]:
    try: m=json.loads(l)
    except: continue
    role=m.get("type")
    t=txt(m)
    if t and t.strip():
        print("="*20, role, "="*20)
        print(t[:1500])
PY

