// win_probe: answer whether the NATIVE Windows CUDA driver supports concurrent
// managed access, which the WSL2 passthrough does not. Driver API only, no
// kernel and no NVRTC, so it needs nothing but nvcuda.dll.
use cudarc::driver::{CudaContext, sys};

fn main() {
    let count = CudaContext::device_count().unwrap_or(0);
    println!("windows driver sees {count} device(s)");
    for d in 0..count as usize {
        match CudaContext::new(d) {
            Err(e) => println!("device {d}: context error {e:?}"),
            Ok(ctx) => {
                let mm = ctx.attribute(sys::CUdevice_attribute::CU_DEVICE_ATTRIBUTE_MANAGED_MEMORY).unwrap_or(-1);
                let cma = ctx.attribute(sys::CUdevice_attribute::CU_DEVICE_ATTRIBUTE_CONCURRENT_MANAGED_ACCESS).unwrap_or(-1);
                println!("device {d}: managed_memory={mm}  concurrent_managed_access={cma}");
            }
        }
    }
}
EOF
