            unsigned char v = (top>0)? stack[--top] : 0;
            if (top < SDEPTH) stack[top++] = (v == 1) ? 1 : 0;
        } else if (tok == 6) {              // FSPLIT
            unsigned char v = (top>0)? stack[top-1] : 0;
