            unsigned int ff = plen; unsigned int depth = 1;
            unsigned int i = (ip + 1) % plen; unsigned int start = i;
            do {
                if (P[i] == 6) depth++;
                else if (P[i] == 7) { depth--; if (depth==0) { ff = i; break; } }
                i = (i + 1) % plen;
            } while (i != start);
