                    for (int a=0,b=k-1;  a<b; a++,b--) { unsigned char t=stack[a]; stack[a]=stack[b]; stack[b]=t; }
                    for (int a=k,b=nn-1; a<b; a++,b--) { unsigned char t=stack[a]; stack[a]=stack[b]; stack[b]=t; }
