            }
        }
        // tok==8 (IMSCRIB) and 12/13/14 (three-way) are excluded from verified programs.

        ip = next_ip;
        // UPDATE: wrap + try_self_modify again
        if (ip >= plen) { ip = 0; if (top > 200) P[ip] = 1; }
