        let (sh, sd) = match mapped(SDEPTH) { Ok(v) => v, Err(e) => return format!("gpu_os run: {e}") };
        let (mh, md) = match mapped(META * 4) { Ok(v) => v, Err(e) => return format!("gpu_os run: {e}") };
        (ch as *mut i32, cd, ph, pd, sh, sd, mh as *mut u32, md)
    };

    // Launch the resident kernel once, async. The host drives it after.
    let cfg = LaunchConfig { grid_dim: (1, 1, 1), block_dim: (1, 1, 1), shared_mem_bytes: 0 };
    let mt = max_ticks;
    {
        let mut b = stream.launch_builder(&func);
        b.arg(&ctrl_d); b.arg(&prog_d); b.arg(&stack_d); b.arg(&meta_d); b.arg(&mt);
        if let Err(e) = unsafe { b.launch(cfg) } { return format!("gpu_os run: launch: {e}"); }
    }

