    unsafe {
        for (i, &id) in ids.iter().enumerate() { write_volatile(prog_h.add(i), id); }
        write_volatile(ctrl_h.add(2), ids.len() as i32); // plen
        write_volatile(ctrl_h.add(0), 1);                // doorbell
    }
