        if unsafe { read_volatile(ctrl_h.add(0)) } == 2 { break; }
        spins += 1;
        if spins > 20_000_000_000 {
            unsafe { write_volatile(ctrl_h.add(1), 1); }
            let _ = stream.synchronize();
            return "gpu_os run: timeout waiting on resident kernel".into();
        }
    }

