        let _ = sys::cuMemFreeHost(ctrl_h as *mut c_void);
        let _ = sys::cuMemFreeHost(prog_h as *mut c_void);
        let _ = sys::cuMemFreeHost(stack_h as *mut c_void);
        let _ = sys::cuMemFreeHost(meta_h as *mut c_void);
    }

